CREATE OR REPLACE PROCEDURE sp(
    arg1 VARCHAR2,
    arg2 NUMBER,
    arg3 VARCHAR2,
    arg4 VARCHAR2
) AS
    v_mascot_match_count NUMBER;
    v_budgeted_avg NUMBER;
    v_enrollment_avg NUMBER;
    v_updated_count NUMBER := 0;

    CURSOR c_budget IS
        SELECT "Budget_invested_percent",
               "total_budget_percent_budgeted",
               "Budgeted"
        FROM "budget"
        FOR UPDATE;

    CURSOR c_school IS
        SELECT "Mascot",
               "Enrollment"
        FROM "School"
        FOR UPDATE;
BEGIN
    SAVEPOINT sp_savepoint;

    SELECT COUNT(*)
    INTO v_mascot_match_count
    FROM "School"
    WHERE "Mascot" = arg3;

    IF v_mascot_match_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20002, 'No School record matches the mascot; budget updates skipped');
    END IF;

    SELECT AVG("Budgeted")
    INTO v_budgeted_avg
    FROM "budget";

    SELECT AVG("Enrollment")
    INTO v_enrollment_avg
    FROM "School";

    FOR r_budget IN c_budget LOOP
        IF r_budget."Budget_invested_percent" = arg1
           AND r_budget."total_budget_percent_budgeted" <= arg2
           AND r_budget."Budgeted" > v_budgeted_avg THEN
            UPDATE "budget"
            SET "total_budget_percent_budgeted" = arg2
            WHERE CURRENT OF c_budget;
            v_updated_count := v_updated_count + 1;
        END IF;
    END LOOP;

    FOR r_school IN c_school LOOP
        IF r_school."Mascot" = arg3
           AND r_school."Enrollment" > v_enrollment_avg THEN
            UPDATE "School"
            SET "Location" = arg4
            WHERE CURRENT OF c_school;
            v_updated_count := v_updated_count + 1;
        END IF;
    END LOOP;

    IF v_updated_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO sp_savepoint;
        RAISE;
END sp;

